function setNote(pack, slide, script, questions, answer, preparation) {
  const previous = pack.notes[slide.id]
  if (!previous) throw new Error(`Missing semester 7 note: ${slide.id}`)
  pack.notes[slide.id] = { ...previous, script, questions, answer,
    ...(preparation ? { preparation } : {}),
    estimatedSeconds: Math.round(script.trim().split(/\s+/).length / 2.1 + (slide.task ? 60 : 15)),
  }
}

function replaceTasks(group, review, bank, offset) {
  const multiple = group.find(slide => slide.task?.type === 'multiple')
  const short = group.find(slide => slide.task?.type === 'short')
  const matching = group.find(slide => slide.task?.type === 'matching')
  if (!multiple || !short || !matching) throw new Error('Semester 7 review requires all three stable task types')
  const [prompt, statements, reasons] = review.multiple
  multiple.title = 'Выберите два обоснованных ответа'
  multiple.task = { id: multiple.task.id, type: 'multiple', choose: 2, prompt,
    options: rotate(statements.map((text, i) => ({ id: `o${i + 1}`, text })), offset) }
  bank.keys[multiple.task.id] = { type: 'multiple', correct: ['o1', 'o2'],
    explanation: `${reasons[0]} ${reasons[1]}`,
    optionExplanations: Object.fromEntries(reasons.map((reason, i) => [`o${i + 1}`, reason])) }

  short.title = review.short.numeric ? 'Выполните расчёт' : 'Назовите существенное понятие'
  short.task = { id: short.task.id, type: 'short', prompt: review.short.prompt }
  bank.keys[short.task.id] = { type: 'short', explanation: review.short.explanation,
    ...(review.short.numeric ? { numeric: review.short.numeric } : { accepted: review.short.accepted }) }

  matching.title = 'Установите предметные соответствия'
  matching.task = { id: matching.task.id, type: 'matching', prompt: 'Сопоставьте наблюдение или условие с его техническим смыслом.',
    items: review.matching.map(([text], i) => ({ id: `i${i + 1}`, text })),
    options: rotate(review.matching.map(([, text], i) => ({ id: `o${i + 1}`, text })), (offset % 3) + 1) }
  bank.keys[matching.task.id] = { type: 'matching',
    pairs: Object.fromEntries(review.matching.map((_, i) => [`i${i + 1}`, `o${i + 1}`])),
    explanation: review.matching.map(([left, right]) => `${left} → ${right}.`).join(' ') }
}

function describeVisual(visual) {
  if (!visual) return ''
  if (visual.type === 'comparison') return `${visual.rows.map(row => row.join(' — ')).join('. ')}. ${visual.caption}`
  if (visual.items) return `${visual.items.map(item => `${item.title || item.label}: ${item.text ?? item.value}`).join('; ')}. ${visual.caption}`
  return visual.caption || ''
}

function rebuildBlockNotes({ group, review, ti, qi, pack, bank }) {
  const nonTasks = group.filter(slide => !slide.task)
  const [explain, setup, reasoning, result, error, discussion] = review.context || context[ti][qi]
  const [section, definition, rule, example, transfer, warning, summary] = nonTasks
  // The original worked case is explained before the transfer; its exact altered
  // condition and ready-made answer are no longer read aloud on every earlier slide.
  setNote(pack, section,
    `Поставьте исходную ситуацию: ${setup}\n\nПопросите назвать, какие сведения уже известны и что следует проверить. Пока работаем с исходным случаем; изменённое условие будет предложено на отдельном слайде.`,
    'Какие исходные сведения заданы? Какое свидетельство понадобится первым?',
    `Ориентир исходного разбора: ${reasoning} ${result}`)
  setNote(pack, definition,
    `${explain}\n\nСвяжите понятие с исходной ситуацией: ${setup} Попросите объяснить механизм своими словами. Изменённый случай пока не раскрывайте.`,
    'Как объяснить опорное понятие на исходной ситуации?',
    `${reasoning} ${result}`)
  if (rule.id !== 's07-01-quality-and-failures-s037') {
    setNote(pack, rule,
      `Разберите предметные связи схемы: ${describeVisual(rule.visual)}\n\nОбъясните переход от условий к свидетельству: ${reasoning} Граница применения: ${error}`,
      'Как связаны подписи схемы и исходный случай? Что эта схема не доказывает?',
      `${reasoning} ${result} ${error}`)
  }
  if (example.id !== 's07-01-quality-and-failures-s093') {
    setNote(pack, example,
      `Разберите исходный пример: ${setup}\n\nСначала предложите назвать ожидаемый исход. Затем пройдите рассуждение: ${reasoning}\n\nРезультат: ${result} Отдельный перенос следует далее; не подменяйте его готовым ответом на изменённое условие.`,
      `Каков результат именно исходного примера? ${setup}`,
      `${reasoning} ${result}`)
  }
  const revisedTransfer = transferRevisions[`${ti}-${qi}`]
  if (revisedTransfer) {
    const [question, answer] = revisedTransfer
    transfer.body = question
    transfer.bullets = ['Назовите изменённое условие и предположите результат.', 'Обоснуйте ответ расчётом или механизмом; отделите вывод от его ограничений.']
    setNote(pack, transfer,
      `Самостоятельный случай с изменённым условием: ${question}\n\nДайте группе выполнить расчёт или обосновать исход до разбора. После попытки сопоставьте рассуждения: ${answer}\n\nСравните с исходным примером: что изменилось и почему прежний результат нельзя перенести механически?`,
      question, answer)
  }
  // Transfer keeps its original subject question and answer. After its attempt,
  // warning/summary consolidate the mechanism rather than reread that exact test.
  setNote(pack, warning,
    `Обсудите типичную ошибку блока: ${error}\n\nПопросите назвать, какое свидетельство или ограничение делает такой вывод недопустимым. Вернитесь к механизму исходного примера, не повторяя дословно уже решённый перенос.`,
    'Какое недостающее условие или свидетельство нужно проверить прежде, чем расширять вывод?',
    `${error} ${result}`)
  setNote(pack, summary,
    `Соберите связь «условие — механизм — свидетельство — граница». Для исходного случая итог таков: ${result}\n\nПопросите объяснить одно ограничение без чтения готовой формулировки. Самопроверка дальше содержит отдельные предметные задания.`,
    discussion,
    `${reasoning} ${result}`)

  for (const slide of group.filter(item => item.task)) {
    const task = slide.task, key = bank.keys[task.id]
    const solution = task.type === 'matching'
      ? task.items.map(item => `${item.text} → ${task.options.find(option => option.id === key.pairs[item.id]).text}`).join('\n')
      : task.type === 'short' ? key.numeric ? String(key.numeric.value) : key.accepted.join(' / ')
        : task.options.filter(option => key.correct.includes(option.id)).map(option => option.text).join('\n')
    setNote(pack, slide,
      `Дайте время на самостоятельную попытку: ${task.prompt}\n\nДо ответа не показывайте ключ. После попытки разберите предметное основание: ${key.explanation}\n\nПопросите назвать исходное условие и границу вывода; повторение названия категории без объяснения не заменяет понимание.`,
      task.prompt,
      `Ответ:\n${solution}\n\nРазбор:\n${key.explanation}`)
  }
  return { section, definition, rule, example, transfer, warning, summary }
}

export function applySemester7Review(course, bank, pack) {
  const changedTaskIds = [], reviewedSlideIds = []
  for (let ti = 0; ti < 3; ti++) {
    const lecture = course.lectures[ti]
    if (!lecture?.id.startsWith('s07-')) throw new Error(`Unexpected semester 7 lecture at ${ti}`)
    const opening = lecture.slides.find(slide => slide.id === `${lecture.id}-s011`)
    if (!opening) throw new Error(`Missing subject comparison: ${lecture.id}-s011`)
    const openingSpec = openingComparisons[ti]
    opening.title = openingSpec.title
    opening.kicker = openingSpec.kicker
    opening.bullets = [...openingSpec.bullets]
    delete opening.body
    setNote(pack, opening, openingSpec.script, openingSpec.question, openingSpec.answer, openingSpec.preparation)
    reviewedSlideIds.push(opening.id)
    for (let qi = 0; qi < 8; qi++) {
      const review = reviews[ti][qi]
      const start = 13 + qi * 11, end = start + 10
      const group = lecture.slides.filter(slide => {
        const number = Number(slide.id.slice(-3))
        return number >= start && number <= end
      })
      if (group.length !== 11) throw new Error(`Unexpected semester 7 block ${lecture.id} / ${qi + 1}`)
      replaceTasks(group, review, bank, ti + qi + 1)
      const single = group.find(slide => slide.task?.type === 'single')
      if (ti === 0 && qi === 1) {
        single.task.prompt = 'Критичность и срочность заявок одинаковы. Два инцидента затронули по сто заявок, десять других — по одной; пересечений нет. С чего начать восстановление? Выберите один обоснованный вывод.'
        changedTaskIds.push(single.task.id)
      }
      if (ti === 1 && qi === 6) {
        const explanation = 'Нет: 0,9496 < 0,95 до округления. До порога не хватает (0,95 − 0,9496) × 100 = 0,04 процентного пункта. Положительный запас 0,238 процентного пункта относится к исходному примеру 0,95238095, а не к этому заданию.'
        const key = bank.keys[single.task.id]
        key.explanation = explanation
        key.optionExplanations = Object.fromEntries(single.task.options.map(option => [option.id,
          key.correct.includes(option.id) ? explanation : `Вывод не соответствует исходному сравнению. ${explanation}`]))
        changedTaskIds.push(single.task.id)
      }
      const rule = group.filter(slide => !slide.task)[2]
      if (review.visual) rule.visual = review.visual
      rebuildBlockNotes({ group, review, ti, qi, pack, bank })
      changedTaskIds.push(...group.filter(slide => slide.task && slide.task.type !== 'single').map(slide => slide.task.id))
      reviewedSlideIds.push(...group.map(slide => slide.id))
    }
  }

  const find = id => course.lectures.flatMap(lecture => lecture.slides).find(slide => slide.id === id)
  const set = (id, fields) => Object.assign(find(id), fields)

  // Same R1/R2 input throughout the worked case. A missing ID belongs only to an
  // explicitly separate assessment case, not an invented fifth journal record.
  set('s07-01-quality-and-failures-s079', { body: 'Учебный журнал: три сообщения с requestId R1 и одно с requestId R2. Единица учёта — операция.' })
  const grouping = find('s07-01-quality-and-failures-s082')
  grouping.bullets = ['Группируем три записи с R1 и одну с R2; все четыре исходные строки сохраняем как свидетельства.', 'Определены две операции. Их принадлежность одному инциденту и первопричину проверяют отдельно.']
  setNote(pack, grouping,
    'Разберите ровно четыре выданные записи: R1, R1, R1 и R2. Единица учёта — операция. Группируем первые три записи по R1, четвёртая образует группу R2. Получаем две определённые операции и сохраняем четыре исходных сообщения.\n\nВ этих исходных данных нет строки без requestId. Для такого случая потребовалось бы отдельное условие и отметка неоднозначности, а не выдуманная связь. Две операции не доказывают две независимые причины или два инцидента.',
    'Сколько операций определено и сколько исходных сообщений сохранено?',
    'Две операции R1/R2 и четыре сообщения. Причины и принадлежность общему инциденту из этих ID не следуют.')

  // Software diversity includes comparison AND a defined reaction. Both variants
  // remain subject to the common requirement and are not independent truth oracles.
  const redundancySetup = 'Целые неотрицательные количества и цены в копейках: 3 × 20 и 2 × 50. Два разных вычислителя должны получить итог 160 копеек.'
  set('s07-03-reliability-threats-prevention-s079', { body: 'Хэш помогает обнаружить изменение файла. Теперь сравним две реализации расчёта суммы и выберем реакцию на расхождение.' })
  const redundancy = find('s07-03-reliability-threats-prevention-s082')
  redundancy.title = 'Две реализации обнаруживают расхождение; платёж не выполняют'
  delete redundancy.visual
  redundancy.columns = ['Шаг', 'Расчёт', 'Наблюдение']
  redundancy.rows = [
    ['Вариант A', 'Σ(количество × цена)', '60 коп.: пропущена строка 2'],
    ['Вариант B', '20 + 20 + 20 + 50 + 50', '160 коп.'],
    ['Сравнение', '60 ≠ 160', 'Диагностический отказ'],
    ['После исправления', '160 = 160', 'Отдельная проверка по эталону'],
  ]
  redundancy.body = 'Вход: 3 шт. × 20 коп. и 2 шт. × 50 коп. Состояние не меняют до сравнения; расхождение само не выбирает верный вариант.'
  delete redundancy.bullets
  setNote(pack, redundancy,
    `${redundancySetup}\n\nПервый вариант складывает произведения количества на цену; в дефектной версии цикл пропускает вторую строку и даёт 60. Второй вариант для этих небольших целых количеств складывает цену по одному разу за единицу товара и получает 160. Это два различных способа вычисления одной функции; повторное копирование одного результата не было бы независимой проверкой.\n\nПеред изменением состояния сравниваем результаты. При 60 ≠ 160 платёж не выполняем, сохраняем вход, версии, оба результата и диагностический статус. Само расхождение не назначает правильный вариант: проверяем 3 × 20 + 2 × 50 по требованию. После исправления получаем 160 в обоих вариантах, затем проверяем эталон, нулевое количество и отдельную строку. Совпадение не исключает общий дефект требования.\n\nАльтернативный способ здесь пригоден только для небольших неотрицательных целых количеств и целых цен в копейках. В промышленной реализации отдельно задают переполнение, денежное округление и атомарность побочных эффектов. Это пример механизма обнаружения и безопасной реакции, не обещание абсолютной отказоустойчивости.`,
    'Что делает система при 60 ≠ 160? Доказывает ли согласие двух вариантов правильность общего требования?',
    'При расхождении — диагностический отказ без платежа и разбор по эталону. Согласие не исключает общий дефект требования или общий источник ошибки.',
    `${redundancySetup} Подготовьте две трассы, эталон 160 и состояние без выполненного платежа. Не выдавайте согласие вариантов за доказательство правильности.`)
  for (const number of [79, 80, 81, 83, 84, 85]) {
    const slide = find(`s07-03-reliability-threats-prevention-s${String(number).padStart(3, '0')}`)
    const old = pack.notes[slide.id]
    old.preparation = 'Различайте обнаружение изменения, восстановление из копии и программное сравнение. Программный пример: 3 × 20 + 2 × 50 = 160 копеек; при расхождении нет платежа.'
  }
  const redundancySection = find('s07-03-reliability-threats-prevention-s079')
  setNote(pack, redundancySection,
    'Сначала восстановите различие обнаружения и восстановления: доверенный хэш позволяет заметить изменение файла, доступная независимая копия позволяет восстановить данные. Затем поставьте задачу программной избыточности: одну критичную сумму вычисляют двумя разными способами.\n\nПопросите назвать, что потребуется кроме двух вариантов: сравнение результатов и заранее выбранная реакция. Конкретный разбор суммы появится далее; пока не назначайте ни один вариант безусловным эталоном.',
    'Какие разные задачи решают доверенный хэш, независимая копия и альтернативный вычислитель?',
    'Хэш обнаруживает изменение, копия поддерживает восстановление, альтернативный вычислитель даёт дополнительное сравнение результата. Общие ошибки и зависимости проверяют отдельно.')
  const redundancyRule = find('s07-03-reliability-threats-prevention-s081')
  setNote(pack, redundancyRule,
    `Сравните три меры по таблице. Доверенный хэш даёт обнаружение изменения, доступная независимая копия — возможность восстановления, иная реализация — дополнительную проверку вычисления. Ни одна мера не заменяет автоматически остальные.\n\nДалее будет разбор двух способов расчёта суммы. До него попросите предсказать, почему нужны не только варианты, но и сравнение результатов и заранее выбранная реакция. Не обсуждайте пока изменённый случай с одинаковыми ответами двух валидаторов.`,
    'Чем отличаются обнаружение изменения, восстановление и сравнение вычислений?',
    'Это разные механизмы. Хэш сам не восстанавливает файл; копия не исключает общий отказ носителя; вторая реализация требует сравнения и реакции на расхождение.')
  const redundancySummary = find('s07-03-reliability-threats-prevention-s085')
  setNote(pack, redundancySummary,
    'Соберите границы трёх мер: обнаружение изменения по доверенному эталону, восстановление из доступной независимой копии и сравнение разных программных реализаций. Для программного случая нужны вход, два вычисления, сравнение и реакция до побочного изменения состояния.\n\nРасхождение останавливает платёж и запускает разбор, но не выбирает верный результат автоматически. Согласие не исключает общий дефект требования. Попросите назвать один покрываемый отказ и один общий источник ошибки для каждой меры.',
    'Что добавляет программное сравнение и чего оно не гарантирует?',
    'Оно может обнаружить расхождение вариантов и запустить контролируемую реакцию. Оно само не определяет правильный результат и не исключает общий дефект требования.')

  // Short arithmetic alone is not a temporal arrival-rate bound when retries may
  // spill into a later minute. Keep both the workload case and its limiting scope.
  const cost = find('s07-03-reliability-threats-prevention-s093')
  cost.bullets = ['Для набора из 100 исходных запросов один повтор даёт до 200 попыток. Если все попытки относятся к одной минуте, это до 200 в минуту; задержанные повторы могут накапливаться.', 'Проверяем аварийную нагрузку, задержку, общий бюджет повторов и условие отключения. Повтор не должен создавать дубли записи.']
  setNote(pack, cost,
    'Возьмите один набор из 100 исходных запросов и разрешите по одному повтору: максимум 100 + 100 = 200 попыток. Это предел количества для набора. Утверждение «200 в минуту» дополнительно предполагает, что соответствующие попытки приходятся на ту же минуту; задержки и накопление повторов могут изменить распределение нагрузки во времени.\n\nПроверяйте не только обычный темп, но и аварийные всплески, общий бюджет повторов и условие отключения. Для записей добавляется защита от повторного эффекта. Стоимость меры — нагрузка, время и сопровождение; выигрыш связывают с конкретным временным сбоем.',
    'При каком условии 200 попыток набора можно назвать 200 попытками в минуту?',
    'Когда все учтённые исходные и повторные попытки относятся к этой минуте. Без временной модели это только предел количества попыток набора.')

  return { changedTaskIds, reviewedSlideIds }
}
